import { z } from "zod";

/**
 * Coercions for reading pagination out of `searchParams`. Remember that in
 * Next 16 `searchParams` is a Promise — `await` it before parsing.
 */
export const searchParamsPaginationSchema = z.object({
  page: z.coerce.number().int().min(1).catch(1),
  perPage: z.coerce.number().int().min(1).max(100).catch(25),
  cursor: z.string().optional(),
});

export const searchParamsSortSchema = z.object({
  sort: z.string().max(40).optional(),
  dir: z.enum(["asc", "desc"]).catch("desc"),
});

export function toOffset(page: number, perPage: number): number {
  return (page - 1) * perPage;
}

export type SearchParamsPagination = z.infer<
  typeof searchParamsPaginationSchema
>;
export type SearchParamsSort = z.infer<typeof searchParamsSortSchema>;
  const org = await resolveOrgBySlug(orgSlug);
  if (org === null) {
    notFound();
  }

  // A membership the caller does not have resolves to null, which is the same
  // 404 as an org that does not exist — see `_lib/tenant-context.ts`.
  const actor = await resolveActorForOrg(principal, orgSlug);
  if (actor === null) {
    notFound();
  }
  assertOrgScope(actor, org.id);

  const flags = snapshotFlags(buildFlagContext(actor, org));

  const [projects, notifications, limitChecks] = await Promise.all([
    listProjects(actor, { orgId: org.id, limit: SIDEBAR_PROJECT_LIMIT }),
    listNotifications(actor, {
      orgId: org.id,
      recipientId: actor.userId,
      unreadOnly: true,
      limit: 1,
    }),
    // Evaluated once per navigation so `usePlanLimits()` in the client tree
    // reads a real measurement instead of falling back to "no data".
    Promise.all(
      SHELL_LIMIT_RESOURCES.map((resource) => checkLimit(org.id, resource, 0)),
    ),
  ]);

  return (
    <OrgProvider
      org={org}
      actor={actor}
      flags={flags}
      limitChecks={limitChecks}
    >
      <DashboardShell
        org={org}
        actor={actor}
        flags={flags}
        projects={projects.items.map((row) => row.project)}
        unreadCount={notifications.total}
        pathname={`/${orgSlug}`}
        panel={props.panel}
      >
        {props.children}
      </DashboardShell>
    </OrgProvider>
  );
}
import { text } from "drizzle-orm/sqlite-core";

/**
 * Column fragments every Taskflow table reuses.
 *
 * Conventions enforced here:
 *  - ids are ULID text primary keys
 *  - timestamps are ISO-8601 text, not unix integers
 *  - every tenant-scoped table carries `org_id`
 *  - every soft-deletable table carries `archived_at`
 */

export const nowIso = () => new Date().toISOString();

export const idColumn = (name = "id") => text(name).primaryKey();

export const timestampColumns = {
  createdAt: text("created_at").notNull().$defaultFn(nowIso),
  updatedAt: text("updated_at").notNull().$defaultFn(nowIso),
};

/** Spread into every table that belongs to exactly one organization. */
export const tenantColumns = {
  orgId: text("org_id").notNull(),
};

/** Spread into every table that is archived rather than deleted. */
export const softDeleteColumns = {
  archivedAt: text("archived_at"),
};
"use client";

/**
 * Inbox list with read/unread affordances.
 */
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { cn } from "@/lib/cn";
import { formatRelative } from "@/lib/date";
import type { NotificationId } from "@/types/common";
import type { Notification } from "@/types/notification";
import type { ReactElement } from "react";

export type NotificationListProps = {
  notifications: readonly Notification[];
  onMarkRead: (id: NotificationId) => void;
  onMarkAllRead: () => void;
};

/** Unread first, then newest first — the inbox ordering people expect. */
export function orderInbox(
  notifications: readonly Notification[],
): readonly Notification[] {
  return [...notifications].sort((a, b) => {
    const byRead = Number(a.readAt !== null) - Number(b.readAt !== null);
    if (byRead !== 0) return byRead;
    return b.createdAt.localeCompare(a.createdAt);
  });
}

export function NotificationList(
  props: NotificationListProps,
): ReactElement | null {
  const { notifications, onMarkRead, onMarkAllRead } = props;

  if (notifications.length === 0) {
    return (
      <EmptyState
        title="You are all caught up"
        description="Assignments, mentions and status changes land here."
      />
    );
  }

  const ordered = orderInbox(notifications);
  const unread = ordered.filter((n) => n.readAt === null).length;

  return (
    <section className="notification-list space-y-2">
      <div className="flex items-center justify-between">
        <span className="text-sm text-neutral-500">{unread} unread</span>
        <Button
          variant="ghost"
          size="sm"
          disabled={unread === 0}
          onClick={onMarkAllRead}
        >
          Mark all read
        </Button>
      </div>

      <ul className="divide-y">
        {ordered.map((notification) => (
          <li
            key={notification.id}
            className={cn(
              "flex items-start justify-between gap-3 py-2",
              notification.readAt === null && "bg-indigo-50/50",
            )}
          >
            <Link href={notification.href} className="min-w-0 flex-1">
              <span className="block text-sm font-medium">
                {notification.title}
              </span>
              <span className="block text-sm text-neutral-600">
                {notification.body}
              </span>
              <span className="block text-xs text-neutral-500">
                {formatRelative(notification.createdAt)}
              </span>
            </Link>

            {notification.readAt === null ? (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onMarkRead(notification.id)}
              >
                Mark read
              </Button>
            ) : null}
          </li>
        ))}
      </ul>
    </section>
  );
}
