/**
 * Resolves the app routes that notifications and search hits point at.
 *
 * Routes are keyed by *slugs* and the human issue number, never by ULIDs, so a
 * link has to be built from the stored rows. Path shapes themselves live in
 * `@/lib/url`; this module only supplies the pieces.
 */
import { issuePath, orgPath, projectPath, settingsPath } from "@/lib/url";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import type { IssueId, OrgId, ProjectId } from "@/types/common";

/** Where a link lands when the row it was meant for no longer exists. */
async function orgHome(orgSlug: string | null): Promise<string> {
  return orgSlug === null ? "/" : orgPath(orgSlug);
}

async function orgSlugOf(orgId: OrgId): Promise<string | null> {
  return (await orgRepo.findOrgById(orgId))?.slug ?? null;
}

/** `/acme/projects/web/issues/12` for the issue, or the org home if it is gone. */
export async function issueHref(
  orgId: OrgId,
  issueId: IssueId,
): Promise<string> {
  const orgSlug = await orgSlugOf(orgId);
  if (orgSlug === null) return orgHome(orgSlug);

  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue === null) return orgHome(orgSlug);

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (project === null) return orgHome(orgSlug);

  return issuePath(orgSlug, project.slug, issue.number);
}

/** `/acme/projects/web`, or the org home if the project is gone. */
export async function projectHref(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<string> {
  const orgSlug = await orgSlugOf(orgId);
  if (orgSlug === null) return orgHome(orgSlug);

  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project === null) return orgHome(orgSlug);

  return projectPath(orgSlug, project.slug);
}

/** `/acme/settings/<section>`, e.g. `members` or `billing`. */
export async function settingsHref(
  orgId: OrgId,
  section: string,
): Promise<string> {
  const orgSlug = await orgSlugOf(orgId);
  return orgSlug === null ? "/" : settingsPath(orgSlug, section);
}

