p='src/server/services/notification-service.ts'
s=open(p).read()
start=s.index('let registered = false;')
head=s[:start]
new='''let registered = false;

/** How a refused resource reads in an alert's title; also what dedupes it. */
const LIMIT_LABELS: Readonly<Record<LimitedResource, string>> = {
  seats: "seats",
  projects: "projects",
  issuesPerProject: "issues per project",
  storageMb: "storage",
  apiRequestsPerHour: "API requests",
  webhooks: "webhook endpoints",
};

/** How many owner-role members are scanned when announcing a new member. */
const OWNER_SCAN_LIMIT = 100;

/** The alert for being handed an issue — at creation or afterwards. */
async function notifyAssigned(
  orgId: OrgId,
  issueId: IssueId,
  assigneeId: UserId,
  actorId: UserId | null,
): Promise<void> {
  await notify(orgId, "issue_assigned", [assigneeId], {
    title: "You were assigned an issue",
    body: `Issue ${issueId} is now yours`,
    href: await issueHref(orgId, issueId),
    actorId,
  });
}

/** The workspace owner, plus any other member who holds the owner role. */
async function listOwners(orgId: OrgId): Promise<readonly UserId[]> {
  const org = await orgRepo.findOrgById(orgId);
  if (org === null) return [];

  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: OWNER_SCAN_LIMIT,
    cursor: null,
  });

  return [...new Set([org.ownerId, ...page.items.map((row) => row.userId)])];
}

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    await notifyAssigned(
      payload.orgId,
      payload.issueId,
      payload.assigneeId,
      payload.actorId,
    );
  });

  // Being assigned at creation is an assignment like any other.
  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    await notifyAssigned(
      payload.orgId,
