/**
 * Personal inboxes, alert links and the alerts the app owes people:
 * assignment (also at creation), status changes, new members and full plans.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { PermissionDeniedError } from "@/lib/permissions";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import {
  listNotifications,
  markAllRead,
  markRead,
  notify,
  updatePreference,
} from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import { emit } from "@/lib/event-bus";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { NotificationKind } from "@/types/notification";

let cleanup: () => void;
let detachSearch: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachSearch = searchService.registerSearchListeners();
});

afterAll(() => {
  detachSearch();
  cleanup();
});

afterEach(() => {
  rateLimitState.allowed = true;
  rateLimitState.remaining = 100;
});

function inbox(
  tenant: Tenant,
  actor: Actor,
  recipientId: UserId,
  extra: { kind?: NotificationKind[]; unreadOnly?: boolean; limit?: number; cursor?: string | null } = {},
) {
  return listNotifications(actor, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: extra.unreadOnly ?? false,
    kind: extra.kind,
    limit: extra.limit ?? 25,
    cursor: extra.cursor ?? null,
  });
}

async function alert(tenant: Tenant, userId: UserId, title: string) {
  const [row] = await notify(tenant.org.id, "comment_created", [userId], {
    title,
    body: title,
    href: "/x",
    actorId: null,
  });
  if (!row) throw new Error("no alert written");
  return row;
}

describe("personal inboxes", () => {
  it("refuses reading, marking and configuring somebody else's inbox, whatever the role", async () => {
    const tenant = await createTenant("inbox-personal", "growth");
    const row = await alert(tenant, tenant.userIds.member, "Private");

    for (const role of ["owner", "admin", "viewer"] as const) {
      const intruder = tenant.actors[role];
      await expect(inbox(tenant, intruder, tenant.userIds.member)).rejects.toBeInstanceOf(
        PermissionDeniedError,
      );
      await expect(
        markRead(intruder, { orgId: tenant.org.id, notificationId: row.id }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
      await expect(
        updatePreference(intruder, {
          orgId: tenant.org.id,
          userId: tenant.userIds.member,
          kind: "comment_created",
          inApp: false,
          email: false,
          digestOnly: false,
        }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
    }

    const own = await inbox(tenant, tenant.actors.member, tenant.userIds.member);
    expect(own.items.map((item) => item.id)).toEqual([row.id]);
    const marked = await markRead(tenant.actors.member, {
      orgId: tenant.org.id,
      notificationId: row.id,
    });
    expect(marked.readAt).not.toBeNull();
  });

  it("marks only the caller's own unread alerts read", async () => {
    const tenant = await createTenant("inbox-markall", "growth");
    await alert(tenant, tenant.userIds.member, "Mine 1");
    await alert(tenant, tenant.userIds.member, "Mine 2");
    await alert(tenant, tenant.userIds.admin, "Theirs");

    expect(await markAllRead(tenant.actors.member, tenant.org.id)).toBe(2);

    const theirs = await inbox(tenant, tenant.actors.admin, tenant.userIds.admin, {
      unreadOnly: true,
    });
    expect(theirs.total).toBe(1);
  });

  it("lists exactly the in-app alerts, without gaps or repeats across pages", async () => {
    const tenant = await createTenant("inbox-paging", "growth");
    const recipient = tenant.userIds.member;

    const inApp: string[] = [];
    for (let i = 0; i < 7; i += 1) {
      const channels = i % 3 === 2 ? (["email"] as const) : (["in_app", "email"] as const);
      const row = await notificationRepo.insertNotification(tenant.org.id, {
        orgId: tenant.org.id,
        recipientId: recipient,
        kind: "comment_created",
        title: `n${i}`,
        body: "",
        href: "/x",
        actorId: null,
        channels,
      });
      if (channels.includes("in_app")) inApp.push(row.id);
    }

    const seen: string[] = [];
    let cursor: string | null = null;
    let total = -1;
    do {
      const page = await inbox(tenant, tenant.actors.member, recipient, { limit: 2, cursor });
      total = page.total;
      seen.push(...page.items.map((item) => item.id));
      cursor = page.nextCursor;
    } while (cursor !== null);

    expect(total).toBe(inApp.length);
    expect([...seen].sort()).toEqual([...inApp].sort());
    expect(new Set(seen).size).toBe(seen.length);
  });

  it("hides an alert the member switched off for the inbox", async () => {
    const tenant = await createTenant("inbox-optout", "growth");
    await updatePreference(tenant.actors.viewer, {
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "comment_created",
      inApp: false,
      email: true,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "comment_created", [tenant.userIds.viewer], {
      title: "Muted",
      body: "",
      href: "/x",
      actorId: null,
    });
    expect(rows[0]?.channels).toEqual(["email"]);

    const page = await inbox(tenant, tenant.actors.viewer, tenant.userIds.viewer);
    expect(page.items).toHaveLength(0);
    expect(page.total).toBe(0);
  });
});

describe("alert links", () => {
  it("points issue alerts and search hits at the pages the app serves", async () => {
    const tenant = await createTenant("links", "growth");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Linkable Zulu",
        assigneeId: tenant.userIds.admin,
      }),
    );
    const issuePage = `/${tenant.org.slug}/projects/${tenant.project.slug}/issues/${issue.number}`;

    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Yankee remark",
      parentId: null,
      mentionedUserIds: [tenant.userIds.viewer],
    });

    const assigned = await inbox(tenant, tenant.actors.admin, tenant.userIds.admin, {
      kind: ["issue_assigned"],
    });
    expect(assigned.items.map((item) => item.href)).toEqual([issuePage]);

    const mention = await inbox(tenant, tenant.actors.viewer, tenant.userIds.viewer, {
      kind: ["comment_mention"],
    });
    expect(mention.items.map((item) => item.href)).toEqual([issuePage]);

    const search = (q: string, kinds: ("issue" | "comment" | "project")[]) =>
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q,
        kinds,
        limit: 25,
        cursor: null,
      });

    expect((await search("Zulu", ["issue"])).items[0]?.href).toBe(issuePage);
    const commentHit = (await search("Yankee", ["comment"])).items[0];
    expect(commentHit).toMatchObject({ id: comment.id, href: issuePage });
    expect((await search("platform", ["project"])).items[0]?.href).toBe(
