function inbox(
  tenant: Tenant,
  actor: Actor,
  recipientId: UserId,
  extra: { kind?: NotificationKind[]; unreadOnly?: boolean; limit?: number; cursor?: string | null } = {},
) {
  return listNotifications(actor, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: extra.unreadOnly ?? false,
    kind: extra.kind,
    limit: extra.limit ?? 25,
    cursor: extra.cursor ?? null,
  });
}

async function alert(tenant: Tenant, userId: UserId, title: string) {
  const [row] = await notify(tenant.org.id, "comment_created", [userId], {
    title,
    body: title,
    href: "/x",
    actorId: null,
  });
  if (!row) throw new Error("no alert written");
  return row;
