    for (const role of ["owner", "admin", "viewer"] as const) {
      const intruder = tenant.actors[role];
      await expect(inbox(tenant, intruder, tenant.userIds.member)).rejects.toBeInstanceOf(
        PermissionDeniedError,
      );
      await expect(
        markRead(intruder, { orgId: tenant.org.id, notificationId: row.id }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
      await expect(
        updatePreference(intruder, {
          orgId: tenant.org.id,
          userId: tenant.userIds.member,
          kind: "comment_created",
          inApp: false,
          email: false,
          digestOnly: false,
        }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
    }

    const own = await inbox(tenant, tenant.actors.member, tenant.userIds.member);
    expect(own.items.map((item) => item.id)).toEqual([row.id]);
