    const tenant = await createTenant("inbox-paging", "growth");
    const recipient = tenant.userIds.member;

    const inApp: string[] = [];
    for (let i = 0; i < 7; i += 1) {
      const channels = i % 3 === 2 ? (["email"] as const) : (["in_app", "email"] as const);
      const row = await notificationRepo.insertNotification(tenant.org.id, {
        orgId: tenant.org.id,
        recipientId: recipient,
        kind: "comment_created",
        title: `n${i}`,
        body: "",
        href: "/x",
        actorId: null,
        channels,
      });
      if (channels.includes("in_app")) inApp.push(row.id);
    }

    const seen: string[] = [];
    let cursor: string | null = null;
    let total = -1;
    do {
      const page = await inbox(tenant, tenant.actors.member, recipient, { limit: 2, cursor });
      total = page.total;
      seen.push(...page.items.map((item) => item.id));
      cursor = page.nextCursor;
    } while (cursor !== null);

    expect(total).toBe(inApp.length);
    expect([...seen].sort()).toEqual([...inApp].sort());
    expect(new Set(seen).size).toBe(seen.length);
  });

