    expect(marked.readAt).not.toBeNull();
  });

  it("marks only the caller's own unread alerts read", async () => {
    const tenant = await createTenant("inbox-markall", "growth");
    await alert(tenant, tenant.userIds.member, "Mine 1");
    await alert(tenant, tenant.userIds.member, "Mine 2");
    await alert(tenant, tenant.userIds.admin, "Theirs");

    expect(await markAllRead(tenant.actors.member, tenant.org.id)).toBe(2);

    const theirs = await inbox(tenant, tenant.actors.admin, tenant.userIds.admin, {
      unreadOnly: true,
    });
    expect(theirs.total).toBe(1);
  });

  it("lists exactly the in-app alerts, without gaps or repeats across pages", async () => {
    const tenant = await createTenant("inbox-paging", "growth");
    const recipient = tenant.userIds.member;

    const inApp: string[] = [];
    for (let i = 0; i < 7; i += 1) {
      const channels = i % 3 === 2 ? (["email"] as const) : (["in_app", "email"] as const);
      const row = await notificationRepo.insertNotification(tenant.org.id, {
        orgId: tenant.org.id,
        recipientId: recipient,
        kind: "comment_created",
        title: `n${i}`,
        body: "",
        href: "/x",
        actorId: null,
        channels,
      });
      if (channels.includes("in_app")) inApp.push(row.id);
    }

    const seen: string[] = [];
    let cursor: string | null = null;
    let total = -1;
    do {
      const page = await inbox(tenant, tenant.actors.member, recipient, { limit: 2, cursor });
      total = page.total;
      seen.push(...page.items.map((item) => item.id));
      cursor = page.nextCursor;
    } while (cursor !== null);

    expect(total).toBe(inApp.length);
    expect([...seen].sort()).toEqual([...inApp].sort());
    expect(new Set(seen).size).toBe(seen.length);
  });

  it("hides an alert the member switched off for the inbox", async () => {
    const tenant = await createTenant("inbox-optout", "growth");
    await updatePreference(tenant.actors.viewer, {
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "comment_created",
      inApp: false,
      email: true,
      digestOnly: false,
    });

    const rows = await notify(tenant.org.id, "comment_created", [tenant.userIds.viewer], {
      title: "Muted",
      body: "",
      href: "/x",
      actorId: null,
    });
    expect(rows[0]?.channels).toEqual(["email"]);

    const page = await inbox(tenant, tenant.actors.viewer, tenant.userIds.viewer);
    expect(page.items).toHaveLength(0);
    expect(page.total).toBe(0);
  });
});

describe("alert links", () => {
  it("points issue alerts and search hits at the pages the app serves", async () => {
    const tenant = await createTenant("links", "growth");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Linkable Zulu",
        assigneeId: tenant.userIds.admin,
      }),
    );
    const issuePage = `/${tenant.org.slug}/projects/${tenant.project.slug}/issues/${issue.number}`;

    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Yankee remark",
      parentId: null,
      mentionedUserIds: [tenant.userIds.viewer],
    });

    const assigned = await inbox(tenant, tenant.actors.admin, tenant.userIds.admin, {
      kind: ["issue_assigned"],
    });
    expect(assigned.items.map((item) => item.href)).toEqual([issuePage]);

    const mention = await inbox(tenant, tenant.actors.viewer, tenant.userIds.viewer, {
      kind: ["comment_mention"],
    });
    expect(mention.items.map((item) => item.href)).toEqual([issuePage]);

    const search = (q: string, kinds: ("issue" | "comment" | "project")[]) =>
      searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q,
        kinds,
        limit: 25,
        cursor: null,
      });

    expect((await search("Zulu", ["issue"])).items[0]?.href).toBe(issuePage);
    const commentHit = (await search("Yankee", ["comment"])).items[0];
    expect(commentHit).toMatchObject({ id: comment.id, href: issuePage });
    expect((await search("platform", ["project"])).items[0]?.href).toBe(
      `/${tenant.org.slug}/projects/${tenant.project.slug}`,
    );
  });
});

describe("who is told", () => {
  it("tells the owner when somebody joins, and not the person who joined", async () => {
    const tenant = await createTenant("joined", "growth");
    const newcomer = await userRepo.insertUser({
      email: "newcomer@joined.test",
      name: "Newcomer",
      passwordHash: "seed",
    });

    await emit("member.joined", {
      orgId: tenant.org.id,
      actorId: newcomer.id,
      occurredAt: new Date().toISOString() as never,
      memberId: "member-x" as never,
      userId: newcomer.id,
      role: "member",
    });

    const owner = await inbox(tenant, tenant.actors.owner, tenant.userIds.owner, {
      kind: ["member_joined"],
    });
    expect(owner.items).toHaveLength(1);
    expect(owner.items[0]?.href).toBe(`/${tenant.org.slug}/settings/members`);

    const joinerCount = await notificationRepo.countUnread(tenant.org.id, newcomer.id);
    expect(joinerCount).toBe(0);
  });

  it("tells the assignee about somebody else's status change only", async () => {
    const tenant = await createTenant("status", "growth");
    const assigned = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.admin }),
    );
    const unassigned = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Nobody's" }),
    );

    await issueService.moveIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: assigned.id,
      toStatus: "in_progress",
      index: 0,
    } as never);
    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: assigned.id,
      status: "done",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: unassigned.id,
      status: "done",
    });

    const page = await inbox(tenant, tenant.actors.admin, tenant.userIds.admin, {
      kind: ["issue_status_changed"],
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]?.href).toContain(`/issues/${assigned.number}`);
  });

  it("tells an assignee at creation, unless they created the issue", async () => {
    const tenant = await createTenant("assigned-at-creation", "growth");

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.admin }),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }),
    );

    const admin = await inbox(tenant, tenant.actors.admin, tenant.userIds.admin, {
      kind: ["issue_assigned"],
    });
    const member = await inbox(tenant, tenant.actors.member, tenant.userIds.member, {
      kind: ["issue_assigned"],
    });
    expect(admin.items).toHaveLength(1);
    expect(member.items).toHaveLength(0);
  });
});

describe("plan-limit alerts", () => {
  async function limitAlerts(tenant: Tenant) {
    return inbox(tenant, tenant.actors.owner, tenant.userIds.owner, {
      kind: ["plan_limit_reached"],
    });
  }

  it("alerts the owner once per resource until it is read", async () => {
    const tenant = await createTenant("limits", "free");
    await projectService.createProject(tenant.actors.member, {
      orgId: tenant.org.id,
      name: "Second",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    } as never);

    const tryProject = (slug: string) =>
      projectService.createProject(tenant.actors.member, {
        orgId: tenant.org.id,
        name: slug,
        slug,
        key: slug.toUpperCase(),
        description: null,
        visibility: "org",
        leadId: null,
        color: "#6366f1",
        targetDate: null,
      } as never);

    await expect(tryProject("third")).rejects.toThrow();
    await expect(tryProject("fourth")).rejects.toThrow();

    let alerts = await limitAlerts(tenant);
    expect(alerts.items).toHaveLength(1);
    expect(alerts.items[0]?.href).toBe(`/${tenant.org.slug}/settings/billing`);

    // A different resource is a different alert.
    await expect(
      invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "x@limits.test",
        role: "member",
      }),
    ).rejects.toThrow();
    expect((await limitAlerts(tenant)).items).toHaveLength(2);

    // Reading the project alert lets the next refusal alert again.
    const projectAlert = (await limitAlerts(tenant)).items.find((item) =>
      item.title.includes("projects"),
    );
    await markRead(tenant.actors.owner, {
      orgId: tenant.org.id,
      notificationId: projectAlert!.id,
    });
    await expect(tryProject("fifth")).rejects.toThrow();
    alerts = await limitAlerts(tenant);
    expect(alerts.items).toHaveLength(3);
  });

  it("alerts the owner when the owner is the one refused", async () => {
    const tenant = await createTenant("limits-owner", "free");
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id),
    );

    await expect(
      attachmentService.addAttachment(tenant.actors.owner, {
        orgId: tenant.org.id,
        issueId: issue.id,
        filename: "big.bin",
        contentType: "application/octet-stream",
        sizeBytes: 200 * 1024 * 1024,
      }),
    ).rejects.toThrow();

    expect((await limitAlerts(tenant)).items).toHaveLength(1);
  });

  it("never alerts from the periodic recount", async () => {
    const tenant = await createTenant("limits-recount", "free");
    await usageService.recomputeUsage(tenant.org.id);
    expect((await limitAlerts(tenant)).items).toHaveLength(0);
  });
});

